module asyn_fifo(
	input wclk,rclk,wrstn,rrstn,winc,rinc,
	output wfull,rempty,
	input [WIDTH-1:0] wdata,
	output [WIDTH-1:0] rdata
);
//Parameters
parameter WIDTH = 8;
parameter DEPTH = 16;
//Internal wires and regs
wire wen,ren;
reg [$clog2(DEPTH):0] waddr_bin,raddr_bin;
reg [$clog2(DEPTH):0] wptr,rptr;
reg [$clog2(DEPTH):0] wptr_buff,rptr_buff;
wire [$clog2(DEPTH):0] wptr_gray,rptr_gray;
wire [$clog2(DEPTH):0] wptr_syn,rptr_syn;
//Assignments
assign wen=winc&(~wfull);
assign ren=rinc&(~rempty);
assign waddr=waddr_bin[$clog2(DEPTH)-1:0];
assign raddr=raddr_bin[$clog2(DEPTH)-1:0];
//Write Pointer Logic
always@(posedge wclk or negedge wrstn)begin
	if(!wrstn)begin
		waddr_bin<=0;
		wptr<=0;
	end
	else begin
		if(winc&(~wfull))begin
			waddr_bin<=waddr_bin+1;
			wptr<={wptr[$clog2(DEPTH)],^wptr[$clog2(DEPTH)-1:0]};
		end
	end
end
//Read Pointer Logic
always@(posedge rclk or negedge rrstn)begin
	if(!rrstn)begin
		raddr_bin<=0;
		rptr<=0;
	end
	else begin
		if(rinc&(~rempty))begin
			raddr_bin<=raddr_bin+1;
			rptr<={rptr[$clog2(DEPTH)],^rptr[$clog2(DEPTH)-1:0]};
		end
	end
end
//Gray Code Conversion
assign wptr_gray=wptr^(wptr>>1);
assign rptr_gray=rptr^(rptr>>1);
//Buffer Registers
always@(posedge wclk or negedge wrstn)begin
	if(!wrstn)begin
		wptr_buff<=0;
	end
	else begin
		wptr_buff<=wptr_gray;
	end
end
always@(posedge rclk or negedge rrstn)begin
	if(!rrstn)begin
		rptr_buff<=0;
	end
	else begin
		rptr_buff<=rptr_gray;
	end
end
//Full and Empty Signal Generation
assign wptr_syn=wptr_buff^(wptr_buff>>1);
assign rptr_syn=rptr_buff^(rptr_buff>>1);
assign wfull=(wptr=={~rptr_syn[$clog2(DEPTH)],rptr_syn[$clog2(DEPTH)-1:0]});
assign rempty=(rptr==wptr_syn);
endmodule
